#!/bin/bash
# D3 실행 뒤 최종 상태 — 읽기 전용. 서버에 쓰지 않는다(~/maint-o13n21 은 읽기만).
set -u
L=/d/tmp/d3run/final
ssh -o BatchMode=yes cat-prod 'TZ=Asia/Seoul date "+서버 %F %T %Z"; echo "crontab $(crontab -l | sha256sum | cut -d" " -f1)"; echo "INSTALLED_SHA $(cat ~/ops-scripts/INSTALLED_SHA)"; echo "daily_check.sh $(sha256sum < ~/ops-scripts/daily_check.sh | cut -d" " -f1)"; echo "daily_checks.sql $(sha256sum < ~/ops-scripts/daily_checks.sql | cut -d" " -f1)"; echo "SID_LEDGER_SHA $(cat ~/ops-scripts/SID_LEDGER_SHA) sid_ledger.sql $(sha256sum < ~/ops-scripts/sid_ledger.sql | cut -d" " -f1)"; cd ~/crypto_trader/AutoTrader && echo "HEAD $(git rev-parse HEAD)"; echo "추적 변경 $(git status --porcelain --untracked-files=no | wc -l)"; echo "start_66.py $(sha256sum < scripts/prospective/start_66.py | cut -d" " -f1)"; for s in backend db redis db-backup frontend; do c=$(docker compose -f docker-compose.prod.yml ps -q $s); docker inspect --format "$s Image={{.Image}} Created={{.Created}} StartedAt={{.State.StartedAt}} RestartCount={{.RestartCount}} Status={{.State.Status}}" $c; done; for t in latest b5cd1d0 1899b49 ee509cf 7a94472; do echo "tag $t $(docker image inspect --format "{{.Id}}" autotrader-backend:$t 2>&1)"; done; echo "image-new $(cat ~/maint-o13n21/image-new.txt)"; echo "image-before $(cat ~/maint-o13n21/image-before.txt)"; M=~/maint-o13n21; echo "== P0 원문 계수"; for f in $M/*.log; do echo "$(basename $f) 줄 $(wc -l < $f) · Connection is not available $(grep -c "Connection is not available" $f) · 누수 경고 $(grep -c "Connection leak detection" $f)"; done; echo "== 목록"; ls -l --time-style=full-iso $M; echo "== sha256"; cd $M && sha256sum * 2>/dev/null' </dev/null > $L/final-state.txt 2>&1
echo "rc=$?"
grep -cE '[0-9]{8,10}:[A-Za-z0-9_-]{30,}' $L/final-state.txt > $L/token-check.txt
